import { cookies, headers } from 'next/headers'

// Parse an Accept-Language header value and return the highest-priority
// language tag, honoring the optional `q` weighting. Falls back to "unknown"
// when the header is absent or empty.
function preferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) return 'unknown'

  const preferred = acceptLanguage
    .split(',')
    .map((part) => {
      const [tag, ...params] = part.trim().split(';')
      const qParam = params.find((p) => p.trim().startsWith('q='))
      const q = qParam ? Number.parseFloat(qParam.trim().slice(2)) : 1
      return { tag: tag.trim(), q: Number.isNaN(q) ? 0 : q }
    })
    .filter((entry) => entry.tag !== '')
    .sort((a, b) => b.q - a.q)[0]

  return preferred?.tag || 'unknown'
}

export default async function Preferences() {
  const cookieStore = await cookies()
  const headerStore = await headers()

  const theme = cookieStore.get('theme')?.value ?? 'light'
  const language = preferredLanguage(headerStore.get('accept-language'))

  return (
    <section>
      <p>
        Current theme: <strong>{theme}</strong>
      </p>
      <p>
        Preferred language: <strong>{language}</strong>
      </p>
    </section>
  )
}

